import{_ as t}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as o,o as r,c as l,a2 as d}from"./chunks/framework.CqGPl1zp.js";const p="/newx-doc/assets/mall-feature.BD-mo-TR.png",i="/newx-doc/assets/mall-preview.BkOe2rkD.png",a="/newx-doc/assets/%E7%AC%AC%E4%B8%89%E6%AD%A5-01.BGk_LXl7.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.D_hrjFA1.png",n="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.DBPSFIvl.png",y=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"mall/build.md","filePath":"mall/build.md","lastUpdated":null}'),h={name:"mall/build.md"};function s(u,e,m,_,b,f){return r(),l("div",null,[...e[0]||(e[0]=[d('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>项目地址：</p><ul><li>uni-app 商城前端，已经基于 Vue3 重构，对应 <a href="https://gitee.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-mall-uniapp</a> 仓库的 <code>master</code> 分支</li><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>商城的功能，由三部分代码组成：</p><p><img src="'+p+'" alt="功能图"></p><ul><li>后端实现，对应 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mall/" target="_blank" rel="noreferrer"><code>yudao-module-mall</code></a> 模块</li><li>管理后台，对应 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/tree/master/src/views/mall" target="_blank" rel="noreferrer"><code>@/views/mall</code></a> 目录</li><li>用户前台，对应 <a href="https://github.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-mall-uniapp</a> 项目</li></ul><p><img src="'+i+'" alt="功能图"></p><h2 id="_1-功能介绍" tabindex="-1">1. 功能介绍 <a class="header-anchor" href="#_1-功能介绍" aria-label="Permalink to &quot;1. 功能介绍&quot;">​</a></h2><p>主要拆分四大模块：商品中心、交易中心、营销中心、会员中心。如下图所示：</p><p><img src="'+a+'" alt="功能列表"></p><h2 id="_2-后端开启" tabindex="-1">2. 后端开启 <a class="header-anchor" href="#_2-后端开启" aria-label="Permalink to &quot;2. 后端开启&quot;">​</a></h2><p>友情提示：</p><p>① 商城使用到支付，所以需要参考 <a href="./../pay/build">《支付手册》</a> 文档，将支付功能开启。</p><p>② 商城使用到会员，所以需要参考 <a href="./../member/build">《会员手册》</a> 文档，将会员功能开启。</p><p>考虑到编译速度，默认 <code>yudao-module-mall</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-mall</code> 模块</li><li>第二步，导入商城的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h3 id="_2-1-开启模块" tabindex="-1">2.1 开启模块 <a class="header-anchor" href="#_2-1-开启模块" aria-label="Permalink to &quot;2.1 开启模块&quot;">​</a></h3><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-mall</code> 模块的注释。如下图所示：</p><p><img src="'+c+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-mall</code> 模块。如下图所示：</p><p><img src="'+n+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+t+'" alt="刷新 Maven 依赖"></p><h3 id="_2-2-第二步-导入-sql" tabindex="-1">2.2 第二步，导入 SQL <a class="header-anchor" href="#_2-2-第二步-导入-sql" aria-label="Permalink to &quot;2.2 第二步，导入 SQL&quot;">​</a></h3><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/mall.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。</p><p>友情提示：↑↑↑ mall.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><h3 id="_2-3-第三步-重启项目" tabindex="-1">2.3 第三步，重启项目 <a class="header-anchor" href="#_2-3-第三步-重启项目" aria-label="Permalink to &quot;2.3 第三步，重启项目&quot;">​</a></h3><p>重启后端项目，然后访问前端的商城菜单，确认功能是否生效。如下图所示：</p><p><img src="'+a+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了商城的功能 🙂</p><p>常见问题：</p><p>① 为什么会报 Cannot resolve cn.iocoder.boot:yudao-module-member-api:2.2.0-jdk8-snapshot 错误？</p><p>参见 <a href="https://t.zsxq.com/QvNHv" target="_blank" rel="noreferrer">https://t.zsxq.com/QvNHv</a> 解决。</p><h2 id="_3-前端开启" tabindex="-1">3. 前端开启 <a class="header-anchor" href="#_3-前端开启" aria-label="Permalink to &quot;3. 前端开启&quot;">​</a></h2><p>参考 <a href="./../quick-start-front">《快速启动（前端项目）》</a> 文档的「2. uni-app 商城移动端」小节。</p><p>友情提示：</p><p>uniapp 中「首页」「我的」界面，是通过店铺装修所实现。如果觉得默认界面不好看，或者不满足你的页面场景，可以参考 <a href="./diy">《店铺装修》</a> 文档，进行自定义。</p><p>目前内置了 3 套模版，应该可以很好的满足大家的场景：</p><table tabindex="0"><thead><tr><th>全品类</th><th>垂直品类：数码 3C</th><th>端午节活动</th></tr></thead><tbody><tr><td></td><td></td><td></td></tr></tbody></table><h2 id="_4-推荐阅读" tabindex="-1">4. 推荐阅读 <a class="header-anchor" href="#_4-推荐阅读" aria-label="Permalink to &quot;4. 推荐阅读&quot;">​</a></h2><p>微信公众号相关：</p><ul><li><a href="./../member/weixin-mp-login">《微信公众号登录》</a></li><li><a href="./../pay/wx-pub-pay-demo">《微信公众号支付接入》</a></li></ul><p>微信小程序相关：</p><ul><li><a href="./../member/weixin-lite-login">《微信小程序登录》</a></li><li><a href="./../pay/wx-lite-pay-demo">《微信小程序支付接入》</a></li></ul><h2 id="_5-部署说明" tabindex="-1">5. 部署说明 <a class="header-anchor" href="#_5-部署说明" aria-label="Permalink to &quot;5. 部署说明&quot;">​</a></h2><h3 id="_5-1-静态资源" tabindex="-1">5.1 静态资源 <a class="header-anchor" href="#_5-1-静态资源" aria-label="Permalink to &quot;5.1 静态资源&quot;">​</a></h3><p>友情提示：本地体验时，暂时不需要更换静态资源地址。</p><p>但是！！！你部署到测试环境，或者小程序时，必须进行更换。不然，会出现图片等资源无法加载的问题！！！</p><p>在 <code>.env</code> 配置文件中，有 <code>SHOPRO_STATIC_URL</code> 配置项，用于配置商城的静态资源地址，默认是 <code>http://test.yudao.iocoder.cn</code>。</p><p>部署时，你必须改成你自己的静态资源地址，不然会导致商城的静态资源无法加载。</p><p>① 将 <a href="https://gitee.com/yudaocode/yudao-demo/tree/master/yudao-static/mall" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-demo/tree/master/yudao-static/mall</a> 的 <code>static</code> 目录下的图片，上传到你的静态资源服务器的 <code>static</code> 目录上。</p><p>如果你使用七牛 CDN，可以使用 <a href="https://developer.qiniu.com/kodo/5972/kodo-browser" target="_blank" rel="noreferrer">Kodo Browser</a> 批量上传。</p><p>② 将 <code>SHOPRO_STATIC_URL</code> 配置项，改成你的静态资源地址。</p><p>③ 重启前端项目，并通过 Chrome 开发者工具的【Network】标签页，查看是不是你的静态资源地址。</p><p>④ 首页和个人中心的 banner、icon 等图片，参考 <a href="./diy">《店铺装修》</a> 进行替换。</p><h3 id="_5-2-发布为-web-网站" tabindex="-1">5.2 发布为 Web 网站 <a class="header-anchor" href="#_5-2-发布为-web-网站" aria-label="Permalink to &quot;5.2 发布为 Web 网站&quot;">​</a></h3><p>① 修改项目根目录的 <code>.env</code> 配置文件，修改 <code>SHOPRO_BASE_URL</code>、<code>SHOPRO_STATIC_URL</code>、<code>SHOPRO_H5_URL</code> 为你的域名地址。</p><p>② 阅读 HBuilder 的官方文档 <a href="https://zh.uniapp.dcloud.io/quickstart-hx.html" target="_blank" rel="noreferrer">https://zh.uniapp.dcloud.io/quickstart-hx.html</a> 的「发布为Web网站」小节。</p><p>③ 打包按成后，它其实就是一个静态网站，可以通过 Nginx 进行转发。具体的转发配置，参考 <a href="https://juejin.cn/post/7310980511453839375" target="_blank" rel="noreferrer">https://juejin.cn/post/7310980511453839375</a> 文章。</p><h3 id="_5-3-发布为微信小程序" tabindex="-1">5.3 发布为微信小程序 <a class="header-anchor" href="#_5-3-发布为微信小程序" aria-label="Permalink to &quot;5.3 发布为微信小程序&quot;">​</a></h3><p>① 修改项目根目录的 <code>.env</code> 配置文件，修改 <code>SHOPRO_BASE_URL</code>、<code>SHOPRO_STATIC_URL</code>、<code>SHOPRO_H5_URL</code> 为你的域名地址。</p><p>② 阅读 HBuilder 的官方文档 <a href="https://zh.uniapp.dcloud.io/quickstart-hx.html" target="_blank" rel="noreferrer">https://zh.uniapp.dcloud.io/quickstart-hx.html</a> 的「发布为微信小程序」小节。</p><p>注意，微信有各种白名单要配置，可参考 <a href="https://blog.csdn.net/weixin_45966674/article/details/133280890" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_45966674/article/details/133280890</a> 文章。</p><h3 id="_5-4-小程序编辑器真机调试报错-为什么" tabindex="-1">5.4 小程序编辑器真机调试报错，为什么？ <a class="header-anchor" href="#_5-4-小程序编辑器真机调试报错-为什么" aria-label="Permalink to &quot;5.4 小程序编辑器真机调试报错，为什么？&quot;">​</a></h3><p>参见 <a href="https://t.zsxq.com/XPkDJ" target="_blank" rel="noreferrer">https://t.zsxq.com/XPkDJ</a> 帖子。</p><h3 id="_5-5-商城-uniapp-怎么开启多租户" tabindex="-1">5.5 商城 uniapp 怎么开启多租户？ <a class="header-anchor" href="#_5-5-商城-uniapp-怎么开启多租户" aria-label="Permalink to &quot;5.5 商城 uniapp 怎么开启多租户？&quot;">​</a></h3><p>① 默认项目根目录的 <code>.env</code> 配置文件，对应的 <code>SHOPRO_TENANT_ID</code> 可配置默认的租户编号，目前是 1 。</p><p>② 在 [系统管理 -&gt; 租户管理] 菜单，配置租户的“绑定域名”字段时，可配置 uniapp 的 H5 访问域名、或者微信小程序的 appId。</p><p>配置后，可在 uniapp 项目的 <code>sheep/store/app.js</code> 文件中，查看到 <code>#adaptTenant</code> 方法，它会根据当前访问的域名、或者微信小程序的 appId，自动适配到对应的租户。</p><p>在匹配不到的情况下，会使用默认的 <code>SHOPRO_TENANT_ID</code> 租户编号。</p><p>另外，如果访问的 H5 带了 <code>tenantId</code> 参数，会使用该参数作为租户编号！！！</p><h3 id="_5-6-支持-vue-cli-工程结构么" tabindex="-1">5.6 支持 vue-cli 工程结构么？ <a class="header-anchor" href="#_5-6-支持-vue-cli-工程结构么" aria-label="Permalink to &quot;5.6 支持 vue-cli 工程结构么？&quot;">​</a></h3><p>对应 <a href="https://gitee.com/yudaocode/yudao-mall-uniapp/tree/master-cli/" target="_blank" rel="noreferrer"><code>master-cli</code></a> 分支，是基于 vue-cli 的工程结构，大家可以使用哈。（后续会合并到 <code>master</code> 分支）</p><p>具体怎么使用，可见 <a href="https://uniapp.dcloud.net.cn/worktile/CLI.html" target="_blank" rel="noreferrer">https://uniapp.dcloud.net.cn/worktile/CLI.html</a> 官方教程。例如说：<code>npm run dev:h5</code> 启动 H5 项目。</p>',75)])])}const q=o(h,[["render",s]]);export{y as __pageData,q as default};
